-- Phase 34 — Schema v2, Bước 7: bảng `knowledge_assets` + migrate 80
-- Knowledge Asset từ `src/features/knowledge/data/knowledge-seed-data.ts`.
--
-- Áp dụng qua Supabase MCP (apply_migration), track lại ở đây theo convention.
--
-- ⚠️ TÊN BẢNG: `knowledge_assets` (số nhiều, khác hẳn `knowledge_seed` —
-- số ít, 1 trong 9 bảng mồ côi TUYỆT ĐỐI KHÔNG ĐỤNG — và `knowledge_seeds`
-- — số nhiều, bảng Lesson đang chạy thật, 11 dòng). Đã `to_regclass()`
-- xác nhận tên `knowledge_assets` chưa tồn tại trước khi tạo.
--
-- QUAN HỆ VỚI knowledge_seeds (Lesson): mỗi Lesson có nhiều `step`, mỗi step
-- có thể mang 1 `assetId` — đây chính là 80 Knowledge Asset ở bảng này.
-- `assetId` được tra cứu qua `getKnowledgeAssetBySlug()` (đọc code xác
-- nhận) — TRỎ THEO SLUG, KHÔNG PHẢI id kỹ thuật nào khác. Đã xác nhận qua
-- dữ liệu thật: `id === slug` cho CẢ 80/80 dòng nguồn (không có ngoại lệ)
-- — vì vậy migration này CHỈ dùng `slug`, không tạo cột `legacy_id` riêng.

-- ---------------------------------------------------------------------------
-- Schema
--
-- Nguồn có 5 khối field (KnowledgeAssetIdentity/DNA/Relationship/Growth/
-- System, xem `src/features/knowledge/types/knowledge.types.ts`) — rich
-- hơn hẳn "content text" đơn giản. Theo đúng chỉ dẫn "content jsonb hoặc
-- text tùy độ phức tạp nội dung gốc": chọn JSONB vì dữ liệu thật có cấu
-- trúc lồng nhiều tầng thật sự (dna.tags[], relationship.relatedAssets[],
-- growth.reflectionQuestions[], system.*...), không phải văn bản thuần.
--
-- Cột riêng NGOÀI 6 cột tối thiểu của đặc tả (id/slug/type/title/content/
-- created_at/updated_at) — bắt buộc phải có, không phải mở rộng tuỳ ý:
--   summary — mọi UI hiện tại (KnowledgeAssetCard) hiển thị summary làm
--     tóm tắt 2 dòng NGOÀI content đầy đủ; nhét chung vào content jsonb
--     sẽ không lọc/hiển thị nhanh được ở tầng danh sách.
--   status  — nguồn có 4 giá trị thật (DRAFT/REVIEW/PUBLISHED/ARCHIVED,
--     khác 3 giá trị Draft/Published/Hidden của mọi bảng generic khác) —
--     GIỮ NGUYÊN VOCABULARY GỐC (viết hoa, đúng enum KnowledgeStatus),
--     KHÔNG tự ý đổi sang chuẩn Draft/Published/Hidden của dự án — đây là
--     giá trị thật đã publish, đổi vocabulary có rủi ro đánh mất ý nghĩa
--     4 trạng thái nếu sau này có dòng DRAFT/REVIEW/ARCHIVED thật.
--
-- `content` jsonb chứa: body (đúng field `content` gốc, đổi tên "body" để
-- không trùng tên cột cha), language, thumbnail, cover, dna, relationship,
-- growth, system — giữ TOÀN VẸN, không rút gọn field nào.
--
-- `created_at`/`updated_at` LẤY TỪ GIÁ TRỊ THẬT của nguồn (`createdAt`/
-- `updatedAt`, đồng loạt "2026-06-01T00:00:00.000Z" cho cả 80 dòng — mốc
-- seed thật, không phải placeholder) — KHÔNG dùng `now()` tại thời điểm
-- migrate, tránh fabricate ngày tạo giả cho nội dung đã tồn tại từ trước.
-- ---------------------------------------------------------------------------
create table if not exists public.knowledge_assets (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique,
  type        text not null check (type in (
                'ARTICLE','GUIDE','PROMPT','CHECKLIST','TEMPLATE','FRAMEWORK',
                'SOP','PLAYBOOK','WORKFLOW','CASE_STUDY','VIDEO','PDF','FAQ',
                'EXERCISE','REFLECTION','ASSESSMENT','CHEATSHEET','MINDMAP'
              )),
  title       text not null,
  summary     text,
  status      text not null default 'DRAFT'
                check (status in ('DRAFT','REVIEW','PUBLISHED','ARCHIVED')),
  content     jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index if not exists knowledge_assets_type_idx on public.knowledge_assets (type);

alter table public.knowledge_assets enable row level security;

create policy "knowledge_assets_read_published" on public.knowledge_assets
  for select using (status = 'PUBLISHED');
create policy "knowledge_assets_admin" on public.knowledge_assets
  for all using (public.is_app_admin()) with check (public.is_app_admin());

